report Properties "Arrears by Property"
  by dimension
  date due_date
  entity rental_arrears_properties
  role view_reports
  currency KES
  cache 60
  maxrange 1200

  group property_id
  rows "Property"
  labels properties_list.property_id > property_name
  sort owed desc

  # needs rent_invoices.property_id filled (see rental_data_repair.sql)
  invoices = count rent_invoices "Invoices Due"
  unpaid_inv = count rent_invoices where paid_amount=0 "Nothing Paid"
  billed = sum rent_invoices.total_amount "Billed" money
  paid = sum rent_invoices.paid_amount "Paid" money
  owed = billed - paid "Balance Owed" money
  arrears_rate = round(owed / billed * 100) "Arrears %"
  share = share(owed) "Share of Arrears"

  headline {label} has the most arrears: {owed} owed, {arrears_rate}% of what was billed.
  remark arrears_rate !== null && arrears_rate >= 30 | bad | Heavy arrears | {label}: {owed} owed, {arrears_rate}% of the {billed} billed.
  remark owed > 0 | watch | Balance owed | {label} owes {owed} across {invoices} invoices.
  remark true | good | Up to date | {label} has nothing owing in this period.
